def rd(p, cast=int, dflt=0):
    try:
        return cast(open(p).read().strip())
    except Exception:
        return dflt


def txt(p):
    return rd(p, str, "?")


def unwrap_delta(e0, e1, wrap):
    """Nieujemna roznica licznika RAPL z korekta na jedno przewinięcie."""
    d = e1 - e0
    if d < 0:
        d += wrap
    assert 0 <= d < wrap, f"unwrap_delta: {d} not in [0, {wrap})"
    return d


def pkg_w(e0, t0, e1, t1, wrap):
    """Moc pakietu z licznika energii. Licznik moze sie przewinac przy wrap."""
    d = unwrap_delta(e0, e1, wrap)
    dt = t1 - t0
    return round(d / 1e6 / dt, 2) if dt > 0 else None


def trapz(rows, i):
    """Srednia moc jako calka trapezami po realnych znacznikach czasu / czas."""
    if len(rows) < 2:
        return None
    j = sum((a[i] + b[i]) / 2.0 * (b[0] - a[0]) for a, b in zip(rows, rows[1:]))
    return round(j / (rows[-1][0] - rows[0][0]), 2)


def hz_range(s):
    v = float(s)
    if not 0.5 <= v <= 20:
        raise argparse.ArgumentTypeError(f"hz must be in [0.5, 20], got {v}")
    return v


